                    categoria=str(payload.get("categoria", "B1")).strip().upper(),
                    clases_faltadas="No especificada",
                    nombre_instructor=str(payload.get("instructor", "")).strip().upper(),
                    no_horas=2,
                    valor_hora=25000,
                    estado=str(payload.get("estado_pago", "Pendiente Pago")).strip(),
